+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit sold. Tickets are imported once; the variance report compares what
+// sales should have used with what the ledger says was consumed.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, listItems, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/** Ingredient quantities one sale line uses (dish × qty portions). */
+export function saleUse(store, { dishId, qty }) {
+  const dish = getDish(store, dishId);
+  return scaled(getRecipe(store, dish.recipeId), qty);
+}
+
+/**
+ * Records sale lines [{ ticket, soldAt, dishId, qty, row }] and consumes their
+ * ingredients (ref `sale:<ticket>`, at `soldAt`). Every line is checked
+ * against stock first; when an item runs out, throws sale_out_of_stock naming
+ * the line's `row` and changes nothing.
+ */
+export function recordSales(store, lines) {
+  const needed = new Map();
+  const uses = lines.map((line) => {
+    const use = saleUse(store, line);
+    for (const u of use) {
+      const total = round3((needed.get(u.itemId) ?? 0) + u.qty);
+      const available = round3(onHand(store, u.itemId));
+      if (total > available) {
+        const item = getItem(store, u.itemId);
+        throw new AppError("sale_out_of_stock", { row: line.row, item: item.name, available, unit: item.unit });
+      }
+      needed.set(u.itemId, total);
+    }
+    return use;
+  });
+  const before = structuredClone(store.data);
+  try {
+    applySales(store, lines, uses);
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+}
+
+// Writes the sale lines and consumes their ingredients.
+function applySales(store, lines, uses) {
+  store.data.sales ??= [];
+  lines.forEach((line, i) => {
+    const dish = getDish(store, line.dishId);
+    store.data.sales.push({
+      id: store.nextId("sale"),
+      ticket: line.ticket,
+      soldAt: line.soldAt,
+      dishId: line.dishId,
+      recipeId: dish.recipeId,
+      qty: line.qty,
+    });
+    for (const u of uses[i]) {
+      if (u.qty > 0) consume(store, u.itemId, u.qty, { at: line.soldAt, ref: `sale:${line.ticket}` });
+    }
+  });
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold on those days, actual use from every consume movement on those days,
+ * and difference = actual - theoretical. Items where both are zero are left out.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (instant) => {
+    const day = instant.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const theoretical = new Map();
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of scaled(getRecipe(store, s.recipeId), s.qty))
+      theoretical.set(u.itemId, round3((theoretical.get(u.itemId) ?? 0) + u.qty));
+  }
+  const actual = new Map();
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    actual.set(batch.itemId, round3((actual.get(batch.itemId) ?? 0) + m.qty));
+  }
+  return listItems(store)
+    .map((item) => {
+      const t = theoretical.get(item.id) ?? 0;
+      const a = actual.get(item.id) ?? 0;
+      return { itemId: item.id, name: item.name, unit: item.unit, theoretical: t, actual: a, difference: round3(a - t) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0);
+}
